# trackmania.io asks API users to identify their project in the User-Agent
API_HEADERS = {"User-Agent": os.getenv("TMENV_USER_AGENT", "tmenv (trackmania-ai PedroAI, Windows port)")}


def gbx_to_json_cmd():
    "Command line of the GbxToJson converter (GBX.NET 1.x). On Windows the managed dlls run on `dotnet`."
    if sys.platform != "win32":
        return [str(tmenv_root / "gbx-to-json" / "GbxToJson")]
    candidates = [os.getenv("TMENV_DOTNET"), tmenv_root.parents[1] / "tools" / "dotnet" / "dotnet.exe", shutil.which("dotnet")]
    dotnet = next((str(c) for c in candidates if c and Path(c).exists()), None)
    if dotnet is None:
        raise FileNotFoundError("dotnet not found: install the .NET runtime or set TMENV_DOTNET")
    dll = tmenv_root / "gbx-to-json" / "win" / "GbxToJson.dll"
    if not dll.exists():
        _extract_gbx_to_json()
    return [dotnet, str(dll)]


def _extract_gbx_to_json():
    "First use on Windows: extract the managed GbxToJson assemblies from the bundled Linux binary."
    import importlib.util

    spec = importlib.util.spec_from_file_location("extract_bundle", tmenv_root / "gbx-to-json" / "extract_bundle.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    logging.info(f"Extracted GbxToJson for Windows: {module.extract()}")


def gbx_bytes_to_json(gbx_bytes):
    path = Path(tempfile.gettempdir()) / "trackmania" / f"{uuid.uuid1()}.gbx"
    path.parent.mkdir(exist_ok=True, parents=True)
    with open(path, "wb") as f:
        f.write(gbx_bytes)
    try:
        return json.loads(check_output(gbx_to_json_cmd() + [str(path)], encoding="utf-8"))
    finally:
        path.unlink(missing_ok=True)


