@cache
def official_campaign(id):
    # trackmania.io moved official campaigns from /api/officialcampaign/{id} to /api/campaign/seasonal/{id}
    return do_request(
        f"https://trackmania.io/api/campaign/seasonal/{id}", headers=API_HEADERS
    )


@cache
def official_campaigns():
    "Official seasonal campaigns, oldest first (Summer 2020, Fall 2020, ...)."
    campaigns, page, page_count = L(), 0, 1
    while page < page_count:
        data = do_request(f"https://trackmania.io/api/campaigns/seasonal/{page}", headers=API_HEADERS)
        campaigns += data["campaigns"]
        page_count = data.get("pageCount", 1)
        page += 1
    return (
        campaigns.filter(Self["official"])
        .map(Self["id"])
        .map(official_campaign)
        .sorted(Self["publishtime"])
    )


def campaign_maps_uid(campaign):
    return L(campaign["playlist"]).map(Self["mapUid"])


def campaigns_maps_uid(campaigns, slice):
    uids = chain.from_iterable(
        campaign_maps_uid(campaign)[slice] for campaign in campaigns
    )
    return L(uids)


@cache
def campaign(club_id, campaign_id):
    return do_request(
        f"https://trackmania.io/api/campaign/{club_id}/{campaign_id}",
        headers=API_HEADERS,
    )
